const oldActivityAudit=screens.activity;
screens.activity=()=>{const a=book().activities.find(a=>a.id===pageId);if(!a)return oldActivityAudit();const rs=activityMetrics(a).records,roots=book().categories.filter(c=>!c.parent);return oldActivityAudit()+auditPanel('activity-analysis',t('这段活动，怎么花的？','このシーンの、支出の内訳。'),`<div class="audit-amount-list">${roots.map(c=>({c,total:sum(rs.filter(r=>categoryContains(c.id,r.category)),expenseNet)})).filter(x=>x.total).map(x=>`<div><span>${categoryName(x.c)}</span><b>${baseMoney(x.total)}</b></div>`).join('')}</div><div class="audit-days">${[...new Set(rs.map(r=>r.date))].sort().map(date=>`<div><span>${date}</span><b>${baseMoney(sum(rs.filter(r=>r.date===date),expenseNet))}</b></div>`).join('')||empty(t('暂无消费','支出はありません'))}</div>${a.holdEnabled?auditLink('activity-release',t('调整 / 释放未用预留','未使用の確保額を調整・解除'),`data-id="${a.id}"`):''}${auditLink('treat-history',t('查看 / 修正本活动互请明细','このシーンのごちそうを確認・修正'),`data-id="${a.id}"`)}`);};
