const rangeTrendBefore=analysisModule;analysisModule=(id,d,first=false)=>{if(id==='trend'&&analysisRange){const dates=[...new Set(d.rs.map(r=>r.date))].sort();return auditPanel('range-trend',t('按实际日期，看这段消费。','実際の日付で、期間の支出を見る。'),`<p>${analysisRange.start} — ${analysisRange.end} · ${t('跨月不合并同一个日号，不套用整月对比。','月またぎで同じ日番号をまとめず、全月比較を適用しません。')}</p><div class="audit-month-bars">${dates.map(date=>{const amount=sum(d.rs.filter(r=>r.date===date),expenseNet);return `<article><span>${date}</span><b>${baseMoney(amount)}</b><i style="--bar:${Math.min(100,amount/(d.total||1)*300)}%"></i></article>`;}).join('')}</div>`);}return rangeTrendBefore(id,d,first);};
const rangeCaptionBefore=screens.analysis;screens.analysis=()=>{const html=rangeCaptionBefore();return analysisRange?html.replace(`${analysisMonth} ·`,`${analysisRange.start} — ${analysisRange.end} ·`):html;};
render();
screens.startup=()=>`<section class="audit-startup startup-${themeName()}"><span class="startup-edition">${themeName()==='magazine'?'YOHAKU / THE EVERYDAY EDITION':themeName()==='journal'?t('我的生活，第一页。','暮らしの、最初のページ。'):'A LITTLE ROOM FOR TOMORROW'}</span><div class="startup-emblem">${experienceArt[themeName()]}</div><h1>${t('余量','ヨハク')}</h1><span class="startup-wordmark">YOHAKU</span><p>${t('给日常，留一点余量。','日々に、少し余白を。')}</p>${pageButton('home',t('进入我的日常','日々の記録へ'),'','full-button')}<small>${t('启动页设计预览 · 正式应用不额外增加确认步骤','起動画面のデザイン・正式版では確認操作を増やしません')}</small></section>`;
const statesWithStartupBefore=screens['ui-states'];screens['ui-states']=()=>statesWithStartupBefore()+auditPanel('startup',t('品牌与启动页','ブランド・起動画面'),pageButton('startup',t('查看本主题启动页','このテーマの起動画面を見る'),'','audit-link'));
render();
const startupRenderBefore=render;render=()=>{startupRenderBefore();document.querySelector('.app-header').hidden=pageName==='startup';document.querySelector('.bottom-nav').hidden=pageName==='startup';};
render();
